def a_tilde(pt, p, dstart, q=DEFAULT_Q):
    """MLE of a_e = (dstart + e)*p at a field point pt (e = Int(pt)). O(m)."""
    return (p % q) * ((int_of_point(pt, q) + dstart) % q) % q


